import importlib

for mod in ["pypdf", "PyPDF2", "reportlab", "fpdf", "pdfplumber", "fitz", "pikepdf", "pdfkit"]:
    try:
        m = importlib.import_module(mod)
        print(mod, "OK", getattr(m, "__version__", ""))
    except Exception as e:
        print(mod, "MISSING", type(e).__name__)

import os, glob

for base in [".codex/skills/pdf", ".codex/skills/pdf/scripts"]:
    print("==", base, "==")
    if os.path.isdir(base):
        for f in sorted(glob.glob(os.path.join(base, "*"))):
            print(f)
    else:
        print("(not a dir)")

